@retry(times=3, exceptions=(ValueError,))
def flaky(counter):
    counter.append(1)
    if len(counter) < 3:
        raise ValueError('transient')
    return 'ok'

c = []
assert flaky(c) == 'ok' and len(c) == 3, f'calls: {len(c)}'
print('ok')

calls = []
@retry(times=5, exceptions=(ValueError,))
def boom():
    calls.append(1)
    raise KeyError('nope')
try:
    boom()
except KeyError:
    pass
else:
    raise AssertionError('KeyError must propagate immediately')
assert len(calls) == 1, f'calls: {len(calls)}'
assert boom.__name__ == 'boom'

@retry(times=2, exceptions=(ValueError,))
def always_bad():
    raise ValueError('dead')
try:
    always_bad()
except ValueError:
    pass
else:
    raise AssertionError('exhausted retries must re-raise the last error')
assert always_bad.attempts == [1, 2], f'attempts: {always_bad.attempts}'
print('ok')
